'use strict';
const $=id=>document.getElementById(id),KEY='europe-history-atlas-v1';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mapSearch=name=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(name);
let selected=ERAS[0].id,country='',mode='era',records={},storageOK=true,opened=null;
function validateRecords(value){if(!value||typeof value!=='object'||Array.isArray(value))throw Error(L('备份格式不正确','Invalid backup format'));const out={};for(const [id,r]of Object.entries(value)){if(!SITES.some(s=>s.id===id))continue;if(!r||typeof r!=='object'||!['none','wish','visited'].includes(r.status)||typeof r.note!=='string'||r.note.length>20000)throw Error(L('记录格式不正确','Invalid record format'));out[id]={status:r.status,note:r.note};}return out;}
try{const old=localStorage.getItem(KEY);if(old)records=validateRecords(JSON.parse(old));}catch{storageOK=false;}
function storageMessage(){return storageOK?L('参观记录与笔记仅保存在当前浏览器，不会跨设备同步。','Visits and notes are stored in this browser only, without cross-device sync.'):L('浏览器存储不可用或记录无法读取，请导出备份。','Browser storage is unavailable or records could not be read. Export a backup.');}
function save(){try{localStorage.setItem(KEY,JSON.stringify(records));storageOK=true;}catch{storageOK=false;}$('storage-message').textContent=storageMessage();return storageOK;}
const getRecord=id=>records[id]||{status:'none',note:''};
const countryNames=[...new Set(SITES.filter(s=>(!s.continent||s.continent==='europe')).flatMap(s=>s.country.split(' / ')))];
function setStatus(id,status){if(!SITES.some(s=>s.id===id)||!['none','wish','visited'].includes(status))throw Error(L('无效的遗产或状态','Invalid property or status'));records[id]={...getRecord(id),status};save();render();if(opened===id){const y=$('detail-body').scrollTop;renderDetail(id);$('detail-body').scrollTop=y;}}
function statusButtons(s){const r=getRecord(s.id);return `<div class="status" aria-label="${esc(s.name)} — ${L('到访状态','Visit status')}"><button data-status="wish" data-id="${s.id}" aria-pressed="${r.status==='wish'}">${r.status==='wish'?'✓ ':''}${L('想去','Want to visit')}</button><button data-status="visited" data-id="${s.id}" aria-pressed="${r.status==='visited'}">${r.status==='visited'?'✓ ':''}${L('已到访','Visited')}</button></div>`;}
function nameLines(s,detail=false){return `${lang==='zh'?`<p class="name-en"><span lang="en">${esc(s.nameEn)}</span>${detail?copyButton(s,'en'):''}</p>`:detail?`<p class="name-en">${copyButton(s,'en')}</p>`:''}${detail&&s.nameLocal?`<p class="name-local">${L('当地名称：','Local name: ')}<span lang="${s.localLang}">${esc(s.nameLocal)}</span>${copyButton(s,'local')}</p>`:''}`;}
function copyButton(s,language){return ` <button class="copy-inline" data-copy-name="${s.id}" data-language="${language}" aria-label="${language==='en'?L('复制英文名','Copy English name'):L('复制当地名称','Copy local name')}">${L('复制','Copy')}</button>`;}
async function copyPlaceName(button){const s=SITES.find(s=>s.id===button.dataset.copyName);if(!s)return;const name=button.dataset.language==='local'?s.nameLocal:s.nameEn;try{await navigator.clipboard.writeText(name);$('copy-feedback').textContent=L('已复制：','Copied: ')+name;}catch{$('copy-feedback').textContent=L('浏览器未允许自动复制，请选中下面的名称复制。','Automatic copying is unavailable. Select and copy the name below.');$('copy-fallback').hidden=false;$('copy-fallback').value=name;$('copy-fallback').focus();$('copy-fallback').select();}}
function visibleSites(){return SITES.filter(s=>(mode==='journal'||(!s.continent||s.continent==='europe'))&&(mode!=='era'||s.eras.includes(selected))&&(mode!=='country'||!country||s.country.split(' / ').includes(country))&&(mode!=='journal'||getRecord(s.id).status!=='none'||getRecord(s.id).note));}
function renderStatic(){
 document.documentElement.lang=lang==='en'?'en':'zh-CN';document.title=L('历史沿线','History Along the Way');
 for(const node of document.querySelectorAll('[data-zh]'))node.textContent=L(node.dataset.zh,node.dataset.en);
 $('home').setAttribute('aria-label',L('历史沿线：返回时间轴起点','History Along the Way: return to the beginning'));
 $('language').textContent=lang==='zh'?'English':'中文';$('language').setAttribute('aria-label',L('切换到英文','Switch to Chinese'));
 $('detail-language').textContent=lang==='zh'?'English':'中文';$('detail-language').setAttribute('aria-label',L('切换到英文','Switch to Chinese'));
 document.querySelector('.close').setAttribute('aria-label',L('关闭详情','Close details'));
 $('timeline').setAttribute('aria-label',L('选择历史时代','Choose a historical period'));
 $('country').innerHTML=`<option value="">${L('整个欧洲','All Europe')}</option>`+countryNames.slice().sort((a,b)=>countryLabel(a).localeCompare(countryLabel(b),lang)).map(c=>`<option value="${esc(c)}">${esc(countryLabel(c))}</option>`).join('');
 $('storage-message').textContent=storageMessage();
}
function render(){
 renderStatic();
 const model=europeViewModel(),parts=continentParts(model);
 // Keep the stable shell so notes/controls retain their event bindings.
 $('era-mobile').innerHTML=parts.options;$('timeline').innerHTML=parts.timeline;
 $('country').innerHTML=parts.countryOptions;$('country').value=country;
 $('country-tools').hidden=mode!=='country';document.querySelector('aside').hidden=mode!=='era';document.querySelector('.workspace').classList.toggle('without-timeline',mode!=='era');
 $('history').setAttribute('aria-pressed',mode==='era');$('browse').setAttribute('aria-pressed',mode==='country');$('journal').setAttribute('aria-pressed',mode==='journal');
 $('total').textContent=SITES.filter(s=>getRecord(s.id).status==='visited').length;
 $('chapter').innerHTML=parts.content;$('sites').innerHTML=parts.cards;$('result-title').textContent=parts.title;$('count').textContent=parts.count;
 $('records-tools').hidden=mode!=='journal';
}

function navigateEra(id){if(!ERAS.some(e=>e.id===id))throw Error(L('无效时代','Invalid period'));selected=id;mode='era';render();}
function renderDetail(id){const s=SITES.find(s=>s.id===id);if(!s)return;opened=id;$('detail').dataset.site=id;
 $('detail-body').innerHTML=`<div class="location">${esc(countryLabel(s.country))} · ${esc(s.city)}</div><h2 class="detail-title">${esc(s.name)}</h2>${nameLines(s,true)}<div class="place-actions"><a class="map-link" href="${mapSearch(s.nameEn)}" target="_blank" rel="noopener">${L('地图搜索','Search maps')} ↗</a></div><p class="credit">${L('系列遗产可能包含多个地点，地图搜索后请确认具体参观点。','Serial properties include multiple places; confirm the particular stop in the map results.')}</p><p id="copy-feedback" class="credit" role="status" aria-live="polite"></p><input id="copy-fallback" class="copy-fallback" aria-label="${L('可手动复制的地点名称','Place name for manual copying')}" readonly hidden><div class="badges"><span class="badge unesco">${L('世界遗产','World Heritage')} #${s.id}</span><span class="badge">${s.relation}</span></div><h3>${L('为什么与这段历史有关','Historical connection')}</h3><p>${esc(s.why)}</p><h3>${L('现场观察','On-site observations')}</h3><p>${esc(s.see)}</p>${STOPS[s.id]?`<h3>${L('可分别参观的地点','Individual stops')}</h3><p class="credit">${L('这些是遗产内部的参观点，不另计为独立世界遗产。','These are stops within this property, not separate World Heritage inscriptions.')}</p><ul class="stops">${STOPS[s.id].map(([name,why],index)=>`<li><strong>${esc(L(name,STOP_NAMES[s.id][index]))}</strong>${lang==='zh'?`<p class="name-en" lang="en">${esc(STOP_NAMES[s.id][index])}</p>`:''}<p>${esc(L(why,STOP_EN[s.id][index]))}</p><a href="${mapSearch(STOP_NAMES[s.id][index])}" target="_blank" rel="noopener">${L('地图搜索','Search maps')} ↗</a></li>`).join('')}</ul>`:''}<h3>${L('参考问题','A question to consider')}</h3><p class="prompt">${esc(s.question)}</p><h3>${L('关联的历史章节','Related chapters')}</h3><div class="badges">${(s.regionalChapters||[]).map(id=>`<button data-chapter-id="${id}" data-chapter-region="${s.continent}">${esc(L(...REGIONAL_ATLASES[s.continent].chapters.find(c=>c.id===id).title))}</button>`).join('')}${(s.africaChapters||[]).map(id=>`<button data-africa-chapter="${id}">${esc(L(...AFRICA_CHAPTERS.find(c=>c.id===id).title))}</button>`).join('')}${s.eras.map(id=>`<button data-go-era="${id}">${esc(ERAS.find(e=>e.id===id).title)}</button>`).join('')}</div><div class="detail-links"><a href="${s.url}" target="_blank" rel="noopener">${L('UNESCO 官方条目','Official UNESCO entry')} ↗</a><a href="${s.url}maps/" target="_blank" rel="noopener">${L('遗产范围地图','Property boundary maps')} ↗</a></div>${statusButtons(s)}<h3><label for="note">${L('我的观察与笔记','My observations and notes')}</label></h3><textarea id="note" maxlength="20000" placeholder="${L('例如：看到了哪些不同年代的建筑？还有什么问题？','For example: which building periods can I identify? What questions remain?')}">${esc(getRecord(id).note)}</textarea><p class="credit" id="note-status">${L('笔记自动保存在当前浏览器。','Notes save automatically in this browser.')}</p>`;
 $('note').addEventListener('input',ev=>{records[id]={...getRecord(id),note:ev.target.value};$('note-status').textContent=save()?L('已保存到当前浏览器。','Saved in this browser.'):L('保存失败，请导出备份。','Saving failed. Please export a backup.');});
}
function openDetail(id){renderDetail(id);$('detail-body').scrollTop=0;$('detail').showModal();}
function toggleLanguage(){lang=lang==='zh'?'en':'zh';try{localStorage.setItem('europe-history-atlas-language',lang);}catch{}const y=$('detail-body').scrollTop;render();if(opened){renderDetail(opened);$('detail-body').scrollTop=y;}$('feedback').textContent='';}
if(typeof document.createElement==='function')$('europe-main').innerHTML=continentShellHTML(continentParts(europeViewModel()),'timeline',EUROPE_TEMPLATE_IDS);
$('language').onclick=toggleLanguage;$('detail-language').onclick=toggleLanguage;
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.copyName)void copyPlaceName(b);if(b.dataset.era)navigateEra(b.dataset.era);if(b.dataset.step){const i=ERAS.findIndex(e=>e.id===selected);navigateEra(ERAS[i+Number(b.dataset.step)].id);}if(b.dataset.open)openDetail(b.dataset.open);if(b.dataset.status){const id=b.dataset.id;setStatus(id,getRecord(id).status===b.dataset.status?'none':b.dataset.status);}if(b.dataset.goEra){country='';navigateEra(b.dataset.goEra);$('detail').close();}});
$('home').onclick=ev=>{ev.preventDefault();country='';navigateEra(ERAS[0].id);window.scrollTo({top:0,behavior:'smooth'});};
$('history').onclick=()=>{mode='era';render();};$('browse').onclick=()=>{mode='country';render();};$('import-trigger').onclick=()=>$('import').click();
$('era-mobile').addEventListener('change',e=>navigateEra(e.target.value));$('country').addEventListener('change',e=>{country=e.target.value;mode='country';render();});$('journal').onclick=()=>{mode=mode==='journal'?'era':'journal';country='';render();};document.querySelector('.close').onclick=()=>$('detail').close();$('detail').addEventListener('close',()=>{opened=null;});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'europe-history-atlas',version:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='europe-history-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('feedback').textContent=L('备份已导出，包含到访状态与笔记。','Backup exported, including visit status and notes.');};
$('import').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>2000000)throw Error(L('备份文件过大','Backup file is too large'));const data=JSON.parse(await f.text());if(data.format!=='europe-history-atlas'||data.version!==1)throw Error(L('请选择本图谱导出的备份','Choose a backup exported from this atlas'));const incoming=validateRecords(data.records);let added=0,conflicts=0;for(const [id,r]of Object.entries(incoming)){if(records[id]&&(records[id].note||records[id].status!=='none')){conflicts++;continue;}records[id]=r;added++;}const ok=save();render();$('feedback').textContent=L(`已导入 ${added} 条，保留 ${conflicts} 条已有记录。`,`Imported ${added} records; kept ${conflicts} existing records.`)+(ok?'':L('存储不可用，请重新导出备份。',' Storage unavailable; export another backup.'));}catch(e){$('feedback').textContent=L('导入失败：','Import failed: ')+e.message;}finally{ev.target.value='';}};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_heritage_visit_status',description:'Set a heritage visit status in this browser.',inputSchema:{type:'object',properties:{siteId:{type:'string'},status:{type:'string',enum:['none','wish','visited']}},required:['siteId','status'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){setStatus(input?.siteId,input?.status);return{siteId:input.siteId,status:getRecord(input.siteId).status,savedToBrowser:storageOK};}})).catch(()=>{});}catch{}}
render();
let backdropPress=false;const outsideDetail=ev=>{const r=$('detail').getBoundingClientRect();return ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom;};
$('detail').addEventListener('pointerdown',ev=>{backdropPress=ev.target===$('detail')&&outsideDetail(ev);});$('detail').addEventListener('click',ev=>{if(backdropPress&&ev.target===$('detail')&&outsideDetail(ev))$('detail').close();backdropPress=false;});
